class Ticket {
    static int issued = 0;
    final int number;
    Ticket() {
        issued++;
        number = issued;
    }
}
public class Main {
    public static void main(String[] args) {
        Ticket first = new Ticket();
        Ticket second = new Ticket();
        final int[] scores = {1};
        scores[0] = 9;
        System.out.println(first.number + " " + second.number + " " + Ticket.issued);
        System.out.println(scores[0]);
    }
}

